<script setup lang="ts">import{onMounted,ref}from'vue';import DefaultLayout from '@/layouts/DefaultLayout.vue';import{useApi}from'@/composables/useApi';import type{ApiResponse,Order}from'@/types';const api=useApi(),orders=ref<Order[]>([]),error=ref('');const money=(n:number)=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND'}).format(n);async function load(){try{const r=await api.get<ApiResponse<Order[]>>('/orders/me');orders.value=r.data||[]}catch(e){error.value=e instanceof Error?e.message:'Không tải được đơn hàng'}}async function cancel(id:string){if(confirm('Hủy đơn hàng này?')){await api.del(`/orders/${id}`);await load()}}onMounted(load)</script>
<template><DefaultLayout><main class="mx-auto max-w-5xl px-4 py-10"><h1 class="mb-7 text-3xl font-extrabold">Lịch sử đơn hàng</h1><p v-if="error" class="text-red-600">{{ error }}</p><div class="space-y-4"><article v-for="o in orders" :key="o.id" class="rounded-2xl border bg-white p-5 dark:border-slate-800 dark:bg-slate-900"><div class="flex flex-wrap justify-between gap-3"><div><b>{{ o.orderNumber }}</b><p class="text-sm text-slate-500">{{ new Date(o.createdAt).toLocaleString('vi-VN') }}</p></div><span class="font-bold" :class="o.status==='PAID'?'text-emerald-600':o.status==='CANCELLED'?'text-red-500':'text-amber-600'">{{ o.status }}</span></div><div v-for="item in o.items" :key="item.id" class="mt-4 flex justify-between border-t pt-3"><span>{{ item.courseTitleSnapshot }}</span><b>{{ money(item.priceSnapshot) }}</b></div><div class="mt-4 flex justify-end gap-2"><button v-if="o.status==='PENDING'" class="text-red-600" @click="cancel(o.id)">Hủy đơn</button><RouterLink v-if="o.status==='PENDING'" :to="`/checkout/${o.id}`" class="rounded-lg bg-purple-600 px-4 py-2 font-bold text-white">Thanh toán</RouterLink><RouterLink :to="`/payment-result/${o.id}`" class="rounded-lg border px-4 py-2">Chi tiết</RouterLink></div></article><p v-if="!orders.length" class="py-12 text-center text-slate-500">Chưa có đơn hàng.</p></div></main></DefaultLayout></template>
